// The top of the page is one funnel, from scanned to conditionally positive (most to fewest); every row, waiting job and decision count opens its listings.
const FUNNEL_STEPS=[['all','ilan tarandı'],['excluded','elendi'],['active','aday kaldı','all'],['listingDetail','ilan ayrıntısı alındı','active'],['parcelIdentity','ada/parsel belli','listingDetail'],['officialParcel','tapu kaydı bulundu (TKGM)','parcelIdentity'],['verification','sit, yol ve rota kontrolü tamam','officialParcel'],['finalReview','final incelemesi yapıldı','verification'],['positive','koşullu olumlu','finalReview']];
