const drawers=new Map(),openDrawers=new Set();
const tierOf=r=>listTier(r,feedback.get(String(r.id))?.decision);
const byRank=(a,b)=>tierOf(a)-tierOf(b)||(a.rank??Infinity)-(b.rank??Infinity);
function funnelItems(key){const active=all.filter(r=>r.lifecycle!=='excluded');return key==='all'?all:key==='excluded'?all.filter(r=>r.lifecycle==='excluded'):key==='active'?active:key==='positive'?all.filter(r=>r.recommended):active.filter(r=>(r.funnelPassed||[]).includes(key))}
