 if(messaging.blocked)items.push({tone:'blocked',title:`Sahibinden mesaj engeli: ${num(messaging.prepared||0)} mesaj taslağı gönderilemiyor`,sub:`${num(sahibinden.length)} aday bu engeli bekliyor · engel: ${messaging.blocker||'kayıtlı değil'} · son başarılı gönderim ${shortDate(messaging.lastSuccessfulAt)||'—'} · son kontrol ${shortDate(messaging.lastCheckedAt)||'—'}`,rows:sahibinden,facet:{type:'next',key:'sahibinden',contains:true}});
 const groups=new Map();for(const r of active){const step=String(r.nextStep||'');if(!step||r.funnelStage==='complete'||/sahibinden/i.test(step))continue;const g=groups.get(step)||{rows:[],stages:new Set()};g.rows.push(r);g.stages.add(r.funnelStage);groups.set(step,g)}
