 for(const [step,g] of [...groups].sort((a,b)=>b[1].rows.length-a[1].rows.length).slice(0,3-items.length)){const n=g.rows.length,missing=step.startsWith('Eksik: ')?step.slice(7).split(/,\s*/):null;items.push({title:missing?(missing.length===1?`${num(n)} adayda yalnız ${lower(missing[0])} eksik`:`${num(n)} adayda eksik: ${missing.map(lower).join(', ')}`):`${num(n)} aday: ${step}`,sub:`${g.stages.size===1?`Adım: ${stageLabels[[...g.stages][0]]||[...g.stages][0]} · `:''}ilanları görmek için dokun`,rows:g.rows,facet:{type:'next',key:step}})}
 return items.map(item=>({...item,state:{items:item.rows.slice().sort(byRank),facet:{...item.facet,label:item.title},limit:50}}));
